-- Export all 483 secondary-STEM candidates to CSV (one row per secondary segment).
\copy (SELECT location, quran_word_id, word_text_uthmani, word_text_uthmani_simple, segment_id, segment_location, segment_number, segment_kind, segment_pos, segment_form_buckwalter, segment_form_arabic_normalized, segment_lemma_buckwalter, segment_lemma_id, segment_lemma_text, segment_root_buckwalter, segment_root_id, segment_root_text, current_word_head_stem_id, current_word_head_stem_text, primary_stem_segment_id, primary_stem_segment_number, primary_stem_pos, primary_stem_form_arabic_normalized, primary_stem_lemma_id, primary_stem_lemma_text, primary_stem_root_id, primary_stem_root_text, mechanical_candidate_stem_id, mechanical_candidate_stem_text, mechanical_candidate_match_method, mechanical_candidate_is_same_as_head_stem::text AS mechanical_candidate_is_same_as_head_stem, mechanical_candidate_is_existing_stem::text AS mechanical_candidate_is_existing_stem, candidate_status, array_to_string(risk_flags, ';') AS risk_flags, NULL::text AS review_decision, NULL::int AS reviewed_stem_id, NULL::text AS reviewed_stem_text, NULL::text AS review_notes, ('P1{n=' || primary_stem_segment_number || ';pos=' || primary_stem_pos || ';form=' || primary_stem_form_arabic_normalized || ';lemma=' || primary_stem_lemma_id || '/' || COALESCE(primary_stem_lemma_text,'-') || ';root=' || COALESCE(primary_stem_root_id::text,'-') || '/' || COALESCE(primary_stem_root_text,'-') || '} P2{n=' || segment_number || ';pos=' || segment_pos || ';form=' || segment_form_arabic_normalized || ';lemma=' || segment_lemma_id || '/' || COALESCE(segment_lemma_text,'-') || ';root=' || COALESCE(segment_root_id::text,'-') || '/' || COALESCE(segment_root_text,'-') || '}') AS stem_segments_summary FROM seg_stem_candidates ORDER BY quran_word_id, segment_number) TO '/projects/Dashboard/App/docs/feature-018-segment-stems-and-stems-explorer/segment-stem-curation-candidates.csv' WITH (FORMAT csv, HEADER true);
